"""Freeze a fresh climate task before fitting or opening its temporal holdout."""
import datetime,hashlib,json
from pathlib import Path
from prepare_climate import HERE,SOURCE,build
from climate_runtime import ALGORITHM,FEATURE_NAMES,STATIONS,PERIOD,sha
TRIAL=HERE/'trial_01'
def write(path,data):path.write_text(json.dumps(data,ensure_ascii=False,indent=2,allow_nan=False),encoding='utf-8')
def row_digest(row):return hashlib.sha256(json.dumps(row,sort_keys=True,ensure_ascii=False,separators=(',',':')).encode()).hexdigest()
def main():
 TRIAL.mkdir(exist_ok=True)
 for f in ['protocol_frozen.json','split_frozen.json']:
  if (TRIAL/f).exists():raise RuntimeError('Frozen climate protocol cannot be overwritten.')
 rows,sources,audit=build();metadata=json.loads((SOURCE/'metadata_877.json').read_text(encoding='utf-8'))
 refs={part:[{'id':r['id'],'station':r['station'],'date':r['date'],'row_sha256':row_digest(r)} for r in rows if r['split']==part] for part in ['train','dev','test']}
 write(TRIAL/'split_frozen.json',{'schema_version':1,'construction':'Fixed chronological cutoffs chosen before fitting: 2000–2016 train, 2017–2018 dev, 2019–2021-10-31 test. Same date at all four stations always belongs to the same partition. No random split or target-dependent cutoff.','counts':audit['partition_counts'],'rows':refs})
 points=[{'family':'ridge','alpha':a} for a in [1.,100.]]+[
  {'family':'hist_gradient_boosting','loss':'squared_error','max_leaf_nodes':7,'min_samples_leaf':200,'max_iter':200},
  {'family':'hist_gradient_boosting','loss':'squared_error','max_leaf_nodes':15,'min_samples_leaf':100,'max_iter':200},
  {'family':'hist_gradient_boosting','loss':'squared_error','max_leaf_nodes':31,'min_samples_leaf':100,'max_iter':200},
  {'family':'hist_gradient_boosting','loss':'absolute_error','max_leaf_nodes':15,'min_samples_leaf':100,'max_iter':200}]
 intervals=[{'family':'hist_gradient_boosting','loss':'quantile','max_leaf_nodes':leaves,'min_samples_leaf':minimum,'max_iter':250,'quantiles':[.1,.9]} for leaves,minimum in [(7,200),(15,100),(31,100)]]
 protocol={'schema_version':1,'algorithm':ALGORITHM,'trial':'climate_trial_01','frozen_at_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'seed':20261107,
  'task':{'input':'Station plus month/day only.','target':'Observed daily mean temperature, Tem_mean, degrees Celsius.','service':'AI 여행시기 기후 참고: historical seasonal representative daily-mean temperature and 10th–90th conditional quantile range.','not_supported':['current/2026 weather forecast','rainfall or rain probability','daily maximum or minimum forecast','outdoor safety assessment','climate trend extrapolation','personal preference or regional consumption comparison'],'reference_period':['2000-01-01','2021-10-31']},
  'source':{'dataset_id':877,'title':metadata['title'],'portal':'제주데이터허브','portal_url':'https://www.jejudatahub.net/data/view/data/877','metadata_api':'https://www.jejudatahub.net/api/data/view?id=877','metadata_sha256':sha(SOURCE/'metadata_877.json'),'owner':metadata.get('owner'),'createByName':metadata.get('createByName'),'original_source':'기상청 기상자료개방포털','original_source_url':'https://data.kma.go.kr/cmmn/main.do','identity_note':'KMA-origin data publicly posted to the Hub by metadata owner 고성빈; not asserted to be directly produced by 제주빅데이터센터.','license_note':'Do not invent a redistribution license absent from the portal metadata.','files':sources,'audit_sha256':sha(SOURCE/'weather_audit.json'),'physical_quality_audit_sha256':sha(SOURCE/'physical_quality_audit.json')},
  'preprocessing':{'runtime_file':'climate_runtime.py','runtime_sha256':sha(HERE/'climate_runtime.py'),'prepare_file':'prepare_climate.py','prepare_sha256':sha(HERE/'prepare_climate.py'),'target_rules':['CSV headers and values strip only, original bytes preserved','finite numeric Tem_mean in [-30,50] C required','if observed Tem_min/Tem_max contradict mean by >0.01 C, exclude row','missing/nonfinite target excluded; never fill with zero','missing min/max do not remove otherwise valid mean','duplicate station-date is a hard error','no rolling temperature, lag, observed weather, Season label or year supplied as a feature'],'feature_names':FEATURE_NAMES,'dimension':10,'station_order':[s['id'] for s in STATIONS],'calendar':'Validate month/day using leap year 2000. Canonical non-leap day index (Jan1=0); Feb29 maps halfway between Feb28 and Mar1 at 58.5. Annual sin/cos harmonics 1 and 2 use period365.25; fractional-month sin/cos uses month lengths of year2000. Every observed year and every user input uses this same mapping; year is ignored by features.','calendar_period_days':PERIOD,'station_scope':'Four observed station series only; not exact conditions at every attraction.'},
  'split':{'file':'split_frozen.json','sha256':sha(TRIAL/'split_frozen.json'),'train':['2000-01-01','2016-12-31'],'dev':['2017-01-01','2018-12-31'],'test':['2019-01-01','2021-10-31'],'counts':audit['partition_counts'],'immutable':True,'no_random_split':True},
  'baselines':{'fit_scope':'train only; same station and month/day information as the models, no year trend or current weather','point_candidates':['station_month_median','station_calendar_plusminus15_mean','station_calendar_plusminus15_median'],'calendar_window':'circular absolute canonical-day distance <=15 using the same365.25 period','selected':'Lowest pooled dev MAE, tie earlier listed baseline. Freeze choice before test.','interval_reference':'For every baseline also report its train-observed station-month or calendar-window q10/q90, evaluated without fitting to dev/test.'},
  'candidates':{'point':points,'interval_pairs':intervals,'actual_estimator_fit_count':12,'fixed_maximum_fit_count':12,'shared_hgb':{'learning_rate':.05,'l2_regularization':10.,'max_bins':255,'early_stopping':False,'random_state':20261107,'categorical_features':None},'selection':{'point':'Minimum pooled dev MAE, ties minimum dev RMSE, then earlier candidate.','interval_pair':'Minimum mean of dev q10/q90 pinball losses after fixed lower/upper sorting, ties closeness of coverage to0.8, then earlier pair.','fit_scope':'All estimators fit train only; no refit on dev or test.','quantile_crossing':'Sort q10/q90 per row before evaluation and serving; report the unsorted crossing rate. No test-based calibration or widening.'}},
  'test':{'single_open_count_limit':1,'opening':'Persist selection_frozen.json and selected trained components before writing test_opened.json; only then transform/predict/score holdout.','metrics':['point_MAE_C','point_RMSE_C','point_bias_C','per_station_MAE_C','interval_coverage','mean_interval_width_C','q10_q90_mean_pinball_loss','quantile_crossing_rate','per_station_interval_coverage'],'point_adoption_gate':{'pooled_mae_maximum_C':3.,'pooled_mae_ratio_to_best_dev_selected_baseline_max':1.02,'each_station_mae_ratio_to_same_baseline_max':1.10},'interval_adoption_gate':{'nominal_coverage':.8,'minimum_holdout_coverage':.75,'maximum_holdout_coverage':.90,'maximum_mean_width_C':12.},'deployment_gate':'All point and interval gates must pass. Noninferiority within2% is not superiority and must not be advertised as accuracy improvement.','failure_policy':'Preserve research-only artifacts and raw results; no retune, repartition or candidate addition after the one holdout opening.','uncertainty':'Four station observations on the same day and consecutive days are correlated. Report monthly/yearly counts and errors, and use28-day blocked bootstrap if confidence intervals are provided; never treat rows as independent Bernoulli weather guarantees.'},
  'reproducibility':{'freeze_script_sha256':sha(Path(__file__)),'training_script_sha256':sha(HERE/'train_climate.py'),'runtime_sha256':sha(HERE/'climate_runtime.py'),'preparation_sha256':sha(HERE/'prepare_climate.py'),'data_audit':audit},
  'deployment':{'stdlib_only':True,'CPU':True,'GPU_required':False,'live_changes_in_this_task':False,'display':'Historical seasonal reference only; show data endpoint2021-10-31, station and validation coverage. The interval describes variation in daily mean temperature, not daily min/max and not confidence of the seasonal average.'}}
 write(TRIAL/'protocol_frozen.json',protocol)
 print(json.dumps({'protocol_sha256':sha(TRIAL/'protocol_frozen.json'),'split_sha256':sha(TRIAL/'split_frozen.json'),'rows':audit['retained_rows'],'counts':audit['partition_counts'],'estimator_fit_count':12},ensure_ascii=True))
if __name__=='__main__':main()
